 String[] dayNames={"MONDAY","TUESDAY","WEDNESDAY","THURSDAY","FRIDAY","SATURDAY","SUNDAY"};java.util.List<StudyDatabase.Topic> topics=db.topics(week);for(int day=0;day<7;day++){LinearLayout d=surface();TextView dayTitle=txt(dayNames[day],9,lime,true);dayTitle.setLetterSpacing(.13f);d.addView(dayTitle);int count=0;for(StudyDatabase.Topic t:topics)if(t.day==day){count++;LinearLayout item=new LinearLayout(this);item.setGravity(Gravity.CENTER_VERTICAL);CheckBox check=new CheckBox(this);check.setButtonTintList(android.content.res.ColorStateList.valueOf(t.done?lime:muted));check.setChecked(t.done);check.setEnabled(started());check.setOnCheckedChangeListener((v,b)->{db.tick(t.id,b);});item.addView(check);LinearLayout info=col();TextView subject=txt(t.subject.toUpperCase(Locale.ROOT),9,muted,true);subject.setLetterSpacing(.08f);info.addView(subject);TextView title=txt(t.title,13,t.done?muted:Color.rgb(238,241,235),true);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,-2);tp.topMargin=dp(5);info.addView(title,tp);item.addView(info,new LinearLayout.LayoutParams(0,-2,1));d.addView(item);View sep=new View(this);sep.setBackgroundColor(line);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(1));sp.topMargin=dp(9);sp.bottomMargin=dp(8);d.addView(sep); }if(count==0)subText(d,day==5?"CBT and weekly revision":day==6?"Rest or light revision":"No scheduled topic");}
